  $("#addPhaseButton").addEventListener("click",()=>openPhaseEditor());$("#resetPhasesButton").addEventListener("click",resetCustomPhases);$("#phaseList").addEventListener("click",handlePhaseAction);$("#savePhaseButton").addEventListener("click",savePhase);
