function updatePhaseTargets(p){const s=state.session,zone=p.zone||state.day.zone||"—",cad=p.cadence||"Cadencia libre",cadDisplay=/^cadencia libre$/i.test(String(cad).trim())?"Libre":cad;document.documentElement.style.setProperty("--zone-color",zoneColor(zone));$("#targetTime").textContent=compactDuration(p.duration,p.durationSeconds);$("#targetZone").textContent=zone;$("#targetCadence").textContent=cadDisplay;$("#targetHr").textContent=p.hr&&p.hr!=="Según zona"?p.hr:hrTarget(zone,s.maxHr);$("#currentPhaseName").textContent=cleanPhaseName(p.name);$("#livePhaseCounter").textContent=`ETAPA ${p.index+1}/${s.phases.length}`;stopCadencePulse();if(!s.paused&&!s.transition)startCadencePulse();switchPhaseMusic(p)}
