function findTouchScrollContainer(node){
  for(let element=node instanceof Element?node:node?.parentElement;
      element&&element!==document.body;
      element=element.parentElement){
    const style=getComputedStyle(element);
    if(/auto|scroll|overlay/.test(style.overflowY)
       &&element.scrollHeight>element.clientHeight+1)return element
  }
  return document.scrollingElement||document.documentElement
}
function setupPullToRefreshGuard(){
  let startX=0,startY=0,scrollContainer=null;
  const reset=()=>{scrollContainer=null};
  document.addEventListener("touchstart",event=>{
    if(event.touches.length!==1)return;
    const touch=event.touches[0];
    startX=touch.clientX;
    startY=touch.clientY;
    scrollContainer=findTouchScrollContainer(event.target)
  },{passive:true,capture:true});
  document.addEventListener("touchmove",event=>{
    if(event.touches.length!==1||!event.cancelable)return;
    const touch=event.touches[0],
      dx=touch.clientX-startX,
      dy=touch.clientY-startY;
    if(dy<=0||Math.abs(dy)<=Math.abs(dx))return;
    const container=scrollContainer||document.scrollingElement||document.documentElement;
    const isDocument=container===document.scrollingElement
      ||container===document.documentElement
      ||container===document.body;
    const atTop=isDocument
      ?Math.max(window.scrollY||0,document.documentElement.scrollTop||0,document.body.scrollTop||0)<=0
      :container.scrollTop<=0;
    if(atTop)event.preventDefault()
  },{passive:false,capture:true});
  document.addEventListener("touchend",reset,{passive:true,capture:true});
  document.addEventListener("touchcancel",reset,{passive:true,capture:true})
}

