function stopGps(){clearGpsWatch();clearInterval(state.gpsMonitor);state.gpsMonitor=null}
function median(values){const ordered=[...values].sort((a,b)=>a-b),mid=Math.floor(ordered.length/2);return ordered.length%2?ordered[mid]:(ordered[mid-1]+ordered[mid])/2}
function updatePositiveElevation(coords){const s=state.session,alt=Number(coords.altitude),altAccuracy=Number(coords.altitudeAccuracy);if(!Number.isFinite(alt)||(Number.isFinite(altAccuracy)&&altAccuracy>30))return;s.altitudeWindow.push(alt);if(s.altitudeWindow.length>5)s.altitudeWindow.shift();const filtered=median(s.altitudeWindow),threshold=Math.max(2.5,Math.min(6,(Number.isFinite(altAccuracy)?altAccuracy:12)*.18));if(!Number.isFinite(s.elevationAnchor)){s.elevationAnchor=filtered;return}const delta=filtered-s.elevationAnchor;if(delta>=threshold){s.elevation+=delta;s.elevationAnchor=filtered}else if(delta<=-threshold)s.elevationAnchor=filtered}
function onGps(pos){const s=state.session;if(!s)return;const c=pos.coords,now=pos.timestamp||Date.now(),wallNow=Date.now(),accuracy=Number(c.accuracy)||999,recovering=Boolean(s.gpsResumePending),current={lat:c.latitude,lon:c.longitude,t:now,accuracy};s.lastGpsReceived=wallNow;$("#gpsStatus").textContent=`GPS: ±${Math.round(accuracy)} m`;if(s.paused){s.lastPosition=current;s.gpsAnchor=current;s.gpsMotionStreak=0;s.gpsMoving=false;s.gpsLastMotionAt=0;s.gpsSpeedUpdatedAt=0;s.speed=0;s.gpsResumePending=false;s.gpsHiddenAt=0;return}if(accuracy>45){if(!s.gpsMoving||wallNow-s.gpsSpeedUpdatedAt>5000)s.speed=0;return}if(!s.gpsAnchor){s.gpsAnchor=current;s.lastPosition=current;s.speed=0;s.gpsMotionStreak=0;s.gpsMoving=false;s.gpsResumePending=false;s.gpsHiddenAt=0;return}const anchor=s.gpsAnchor,dt=(now-anchor.t)/1000,dist=haversine(anchor.lat,anchor.lon,c.latitude,c.longitude),uncertainty=Math.max(5,Math.min(20,(accuracy+(anchor.accuracy||accuracy))*.35)),sensorSpeed=Number.isFinite(c.speed)&&c.speed>=0?c.speed*3.6:null,derivedSpeed=dt>0?dist/dt*3.6:0,maxGap=recovering?21600:120,plausible=dt>0&&dt<maxGap&&derivedSpeed<=80&&dist<Math.max(recovering?1000:180,dt*22.2),speedEvidence=(sensorSpeed!=null&&sensorSpeed>=1.5)||derivedSpeed>=2.2,candidate=plausible&&dist>uncertainty&&derivedSpeed>=1.5&&speedEvidence;if(candidate)s.gpsMotionStreak=Math.min(2,s.gpsMotionStreak+1);else if(!s.gpsMoving)s.gpsMotionStreak=0;const confirmed=candidate&&(recovering||s.gpsMoving||s.gpsMotionStreak>=2);if(confirmed){const measured=sensorSpeed!=null&&sensorSpeed>=1.5?sensorSpeed:derivedSpeed;s.distance+=dist/1000;s.speed=s.speed>0?s.speed*.55+measured*.45:measured;s.gpsAnchor=current;s.gpsMotionStreak=2;s.gpsMoving=true;s.gpsLastMotionAt=now;s.gpsSpeedUpdatedAt=wallNow;updatePositiveElevation(c)}else if(s.gpsMoving){if(now-s.gpsLastMotionAt>5000){s.gpsMoving=false;s.gpsMotionStreak=0;s.speed=0;s.gpsAnchor=current}}else{s.speed=0;if(dt>120&&!recovering)s.gpsAnchor=current}s.lastPosition=current;s.gpsResumePending=false;s.gpsHiddenAt=0}
function onGpsError(err){$("#gpsStatus").textContent=err.code===1?"GPS: permiso denegado":err.code===3?"GPS: reintentando":"GPS: sin señal";if(err.code===3&&state.session?.gps)setTimeout(()=>{if(state.session)startGps(true)},1500)}
function haversine(a,b,c,d){const R=6371000,x=(c-a)*Math.PI/180,y=(d-b)*Math.PI/180,q=Math.sin(x/2)**2+Math.cos(a*Math.PI/180)*Math.cos(c*Math.PI/180)*Math.sin(y/2)**2;return 2*R*Math.asin(Math.sqrt(q))}
function trainingRecords(){try{return JSON.parse(localStorage.getItem("rpc.trainingRecords")||"[]")}catch{return []}}
function totalPlannedTrainings(){return state.data?.weeks?.reduce((sum,w)=>sum+Object.keys(w.days||{}).length,0)||0}
function saveTrainingRecord(){const s=state.session;if(!s)return;const avgSpeed=averageSessionSpeed(s),avgHr=s.sampleSeconds&&s.hrWeighted?s.hrWeighted/s.sampleSeconds:0,completed=s.phaseResults.map((r,i)=>({...r,index:i,name:cleanPhaseName(s.phases[i].name),planned:s.phases[i].durationSeconds})).filter(r=>r.status==="completed"),completedSeconds=completed.reduce((sum,r)=>sum+r.planned,0),record={id:`${Date.now()}-${state.week.number}-${state.dayName}`,date:new Date().toISOString(),week:state.week.number,day:state.dayName,title:state.day.title,plannedDuration:s.plannedTotal,actualDuration:s.averageElapsed,phaseDuration:s.totalElapsed,completedDuration:completedSeconds,completion:s.plannedTotal?Math.min(100,Math.round(completedSeconds/s.plannedTotal*100)):0,completedPhases:completed,skippedPhases:s.phaseResults.filter(r=>r.status==="skipped").length,objectives:{zone:state.day.zone||"—",cadence:state.day.cadence||"Cadencia libre",distance:state.day.distance||"—",phases:s.phases.map(p=>({name:cleanPhaseName(p.name),duration:p.duration,zone:p.zone,cadence:p.cadence,hr:p.hr}))},actual:{distance:Number(s.distance.toFixed(2)),avgSpeed:Number(avgSpeed.toFixed(1)),elevation:Math.round(s.elevation),avgHr:Math.round(avgHr)}},records=trainingRecords();records.push(record);localStorage.setItem("rpc.trainingRecords",JSON.stringify(records));renderProgressCard()}
function progressData(){const records=trainingRecords(),total=totalPlannedTrainings(),unique=new Set(records.filter(r=>r.completion>=100).map(r=>`${r.week}-${r.day}`)).size,percent=total?Math.min(100,Math.round(unique/total*100)):0;return {records,total,unique,percent}}
function renderProgressCard(){if(!state.data||!$("#progressCard"))return;const d=progressData();$("#progressPercent").textContent=`${d.percent}%`;$("#progressSummary").textContent=`${d.unique} de ${d.total} entrenamientos`;$("#progressWeeks").textContent=`Plan de ${state.data.weeks.length} semanas`;$("#progressDonut").style.setProperty("--progress",d.percent)}
function deleteTrainingRecord(id){const records=trainingRecords(),record=records.find(r=>r.id===id);if(!record)return;const date=new Date(record.date).toLocaleDateString("es-AR"),label=`Semana ${record.week} · ${record.day} · ${date}`;if(!confirm(`¿Desea eliminar el registro de entrenamiento de ${label}?`))return;localStorage.setItem("rpc.trainingRecords",JSON.stringify(records.filter(r=>r.id!==id)));renderProgressCard();openHistory()}
function openHistory(){const d=progressData(),list=$("#historyList"),dialog=$("#historyDialog");$("#historySummary").innerHTML=`<strong>${d.percent}% completado</strong><span>${d.unique} de ${d.total} entrenamientos del plan</span>`;list.innerHTML=d.records.length?[...d.records].reverse().map(r=>`<details class="history-record"><summary><span>Semana ${r.week} · ${escapeHtml(r.day)}</span><span class="history-record-date"><strong>${new Date(r.date).toLocaleDateString("es-AR")}</strong><button class="history-delete-button" type="button" data-record-id="${escapeHtml(r.id)}" aria-label="Eliminar registro del ${new Date(r.date).toLocaleDateString("es-AR")}" title="Eliminar registro">×</button></span></summary><div class="history-columns"><section><h3>OBJETIVOS</h3><p>Duración: ${formatClock(r.plannedDuration,true)}</p><p>Zona: ${escapeHtml(r.objectives.zone)}</p><p>Cadencia: ${escapeHtml(r.objectives.cadence)}</p><p>Distancia: ${escapeHtml(r.objectives.distance)}</p></section><section><h3>REGISTRADO</h3><p>Duración: ${formatClock(r.actualDuration,true)}</p><p>Cumplimiento: ${r.completion}%</p><p>Etapas completadas: ${r.completedPhases?.length||0}/${r.objectives.phases.length}</p><p>Etapas omitidas: ${r.skippedPhases||0}</p><p>Distancia: ${r.actual.distance.toFixed(2)} km</p><p>Velocidad media: ${r.actual.avgSpeed.toFixed(1)} km/h</p><p>Desnivel: +${r.actual.elevation} m</p><p>FC media: ${r.actual.avgHr||"—"} ppm</p></section></div></details>`).join(""):'<p class="empty-history">Todavía no hay entrenamientos guardados.</p>';list.querySelectorAll(".history-delete-button").forEach(button=>button.addEventListener("click",event=>{event.preventDefault();event.stopPropagation();deleteTrainingRecord(button.dataset.recordId)}));if(!dialog.open)dialog.showModal()}
function setupInstallPrompt(){const hint=$("#installHint");addEventListener("beforeinstallprompt",event=>{event.preventDefault();state.deferredInstall=event;hint.hidden=false;hint.textContent="Tocá aquí para instalar la aplicación.";hint.setAttribute("role","button");hint.tabIndex=0});const install=async()=>{if(!state.deferredInstall)return;state.deferredInstall.prompt();await state.deferredInstall.userChoice;state.deferredInstall=null;hint.hidden=true};hint.addEventListener("click",install);hint.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" ")install()});addEventListener("appinstalled",()=>{state.deferredInstall=null;hint.hidden=true})}
async function requestWakeLock(){try{if(!("wakeLock" in navigator)||document.visibilityState!=="visible")return;if(state.wakeLock&&!state.wakeLock.released)return;state.wakeLock=await navigator.wakeLock.request("screen");state.wakeLock.addEventListener("release",()=>{state.wakeLock=null;if(document.visibilityState==="visible"&&state.session&&!state.session.finished)setTimeout(requestWakeLock,500)},{once:true})}catch{}}
function releaseWakeLock(){try{state.wakeLock?.release()}catch{}state.wakeLock=null}
document.addEventListener("visibilitychange",()=>{const s=state.session;keepSpeechActive();if(!s||s.finished)return;if(document.visibilityState==="hidden"){s.gpsHiddenAt=Date.now();s.gpsResumePending=Boolean(s.gps);keepSpeechActive();return}tick();requestWakeLock();keepSpeechActive();if(s.gps&&(s.gpsHiddenAt||Date.now()-s.lastGpsReceived>12000))startGps(true);const p=s.phases?.[s.phaseIndex];if(s.voiceEnabled&&p&&s.transition&&!state.speechUtterance)speakPhase(p);if(s.musicEnabled&&!s.musicPausedByUser&&state.musicAudio?.paused)playMusicReliably()});
function escapeHtml(v){return String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]))}addEventListener("popstate",()=>{if(!location.hash&&state.session)$("#finishDialog").showModal();else if(!location.hash)closePrepare()});init().catch(err=>{document.body.innerHTML=`<main class="app"><section class="card"><h2>Error</h2><p>${escapeHtml(err.message)}</p></section></main>`});

